import{_ as n,C as i,c as l,o as g,a3 as r,G as o,j as s,a}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Create a project","description":"","frontmatter":{},"headers":[],"relativePath":"master/services/project/project-management/create-project.md","filePath":"master/services/project/project-management/create-project.md","lastUpdated":1793074831000}'),c={name:"master/services/project/project-management/create-project.md"};function h(d,t,p,m,u,f){const e=i("ImagePopup");return g(),l("div",null,[t[0]||(t[0]=r('<h1 id="create-a-project" tabindex="-1">Create a project <a class="header-anchor" href="#create-a-project" aria-label="Permalink to &quot;Create a project&quot;">​</a></h1><p>A project groups the tasks, people, dates and hours of one job. The project list shows every project as a card. You can filter the cards, mark favorites, and open a project to see its details.</p><blockquote><p><strong>In simple words:</strong> Open the project list, click <strong>New Project</strong>, fill the form and click <strong>Create</strong>.</p></blockquote><p>Open <code>Project → Projects</code>.</p><div class="info custom-block"><p class="custom-block-title">About the example</p><p>This page creates a second project, <strong>Customer Portal Launch</strong>, so the pictures show a fresh form. The rest of the guide uses <strong>Website Revamp</strong>. Create both if you want to follow every page.</p></div><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>Add <a href="./project-stages-and-milestones.html">project stages</a> if <strong>Enable Project Stages</strong> is on.</li><li>Create the customer in <a href="./../../../getting-started/contacts/contacts.html">Contacts</a>.</li><li>Switch on the features you need in <a href="./../get-started/project-settings.html">Project settings</a>.</li></ul></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Projects appear as cards, not as a table. Each card shows the name, the customer, the planned dates, the project manager and the tags. A badge with remaining hours appears when timesheets and milestones are on for the project.</p>',8)),o(e,{src:"/images1/project/pj_list_cards.png",alt:"Project list as cards showing Customer Portal Launch, Internal IT Upgrade, ERP Implementation and Website Revamp with customer, dates, manager and tags"}),t[1]||(t[1]=r('<h3 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h3><ul><li><strong>Default:</strong> every project.</li><li><strong>My Projects:</strong> projects where you are the project manager.</li><li><strong>My Favorites:</strong> projects you marked with the star.</li><li><strong>Unassigned Projects:</strong> projects with no project manager.</li><li><strong>Archived Projects:</strong> projects you deleted. You can restore them.</li></ul><h3 id="group-by-filters-and-search" tabindex="-1">Group by, filters and search <a class="header-anchor" href="#group-by-filters-and-search" aria-label="Permalink to &quot;Group by, filters and search&quot;">​</a></h3><p>Group the cards by <strong>Stage</strong>, <strong>Project Manager</strong>, <strong>Customer</strong> or <strong>Created At</strong>. Use the search box to find a project by name. Open the filter panel to narrow the list. You can filter by <strong>Name</strong>, <strong>Visibility</strong>, dates, <strong>Stage</strong>, <strong>Customer</strong>, <strong>Project Manager</strong> and <strong>Tags</strong>.</p>',4)),o(e,{src:"/images1/project/pj_list_filters.png",alt:"Filters panel of the project list with the Add rule menu listing Name, Visibility, Start Date, End Date, Stage, Customer and more"}),t[2]||(t[2]=r('<h3 id="card-buttons" tabindex="-1">Card buttons <a class="header-anchor" href="#card-buttons" aria-label="Permalink to &quot;Card buttons&quot;">​</a></h3><ul><li><strong>Star:</strong> marks the project as your favorite. It then shows in <strong>My Favorites</strong>.</li><li><strong>Tasks:</strong> shows the number of tasks. Click it to open the tasks of that project.</li><li><strong>Milestones badge:</strong> shows completed over total, for example 1/2. It appears when <strong>Enable Milestones</strong> and <strong>Allow Milestones</strong> are on.</li><li><strong>Three dot menu:</strong> <strong>Edit</strong>, <strong>Delete</strong>, <strong>Restore</strong> and <strong>Force delete</strong>.</li></ul><h2 id="create-project" tabindex="-1">Create project <a class="header-anchor" href="#create-project" aria-label="Permalink to &quot;Create project&quot;">​</a></h2><ol><li>Click <strong>New Project</strong>. The page is titled <strong>Create Project</strong>.</li></ol>',4)),o(e,{src:"/images1/project/pj_create_empty.png",alt:"Empty Create Project form with the stage bar, General card, Additional Information card and Settings card"}),t[3]||(t[3]=r('<ol start="2"><li>If the stage bar shows, keep <strong>To Do</strong> or click another stage. It needs <strong>Enable Project Stages</strong>. The first stage is chosen for you.</li></ol><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ol start="3"><li>Type <strong>Customer Portal Launch</strong> in <strong>Name</strong>. Add a short <strong>Description</strong> if you like.</li></ol><ul><li><strong><em>Name:</em></strong> Required. Up to 255 characters.</li><li><strong><em>Description:</em></strong> Free text with formatting.</li></ul><h3 id="additional-information" tabindex="-1">Additional Information <a class="header-anchor" href="#additional-information" aria-label="Permalink to &quot;Additional Information&quot;">​</a></h3><ol start="4"><li>Choose <strong>ERP Admin</strong> as <strong>Project Manager</strong>.</li><li>Choose <strong>Azure Interiors</strong> as <strong>Customer</strong>.</li><li>Set <strong>Start Date</strong> to 03 Aug 2026 and <strong>End Date</strong> to 31 Oct 2026.</li><li>If you switched on <strong>Enable Timesheets</strong>, enter <strong>80</strong> in <strong>Allocated Hours</strong>. Otherwise the field is hidden.</li><li>Pick the tag <strong>Client Work</strong> in <strong>Tags</strong>.</li></ol>',6)),o(e,{src:"/images1/project/pj_create_additional.png",alt:"Additional Information card with Project Manager ERP Admin, Customer Azure Interiors, dates 03 Aug 2026 to 31 Oct 2026 and Allocated Hours 80"}),t[4]||(t[4]=r('<ul><li><strong><em>Project Manager:</em></strong> The user who runs the project. Click the plus icon in the field to add a user.</li><li><strong><em>Customer:</em></strong> The company or person the work is for. Click the plus icon in the field to create a contact without leaving the form.</li><li><strong><em>Start Date</em> and <em>End Date:</em></strong> Fill both or neither. The end date cannot be before the start date.</li><li><strong><em>Allocated Hours:</em></strong> The planned hours. Use decimals: 1.5 means 1 hour 30 minutes. Shown only when <strong>Enable Timesheets</strong> is on.</li><li><strong><em>Tags:</em></strong> Labels from <a href="./../configuration/tags.html">Tags</a>. You can create a tag here.</li><li><strong><em>Company:</em></strong> The company that owns the project. It matters when you run more than one company in Aureus.</li></ul><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ol start="9"><li>In the <strong>Settings</strong> card on the right, leave <strong>Visibility</strong> on <strong>Internal</strong>. Switch on <strong>Allow Timesheets</strong> and <strong>Allow Milestones</strong>.</li></ol><ul><li><strong><em>Visibility:</em></strong><ul><li><strong>Private</strong> for invited internal users only.</li><li><strong>Internal</strong> for all internal users (default). An internal user is a person with an Aureus login. A portal user is a customer with portal access. See <a href="./../../../general-settings/users/portal-access.html">Portal access</a>.</li><li><strong>Public</strong> for invited portal users and all internal users.</li></ul></li><li><strong><em>Allow Timesheets:</em></strong> Lets people log hours on the project tasks. Needs <strong>Enable Timesheets</strong>.</li><li><strong><em>Allow Milestones:</em></strong> Lets you add milestones. Needs <strong>Enable Milestones</strong>. It is on by default.</li></ul>',4)),o(e,{src:"/images1/project/pj_create_settings.png",alt:"Settings card with Visibility Internal, Allow Timesheets on and Allow Milestones on"}),t[5]||(t[5]=s("ol",{start:"10"},[s("li",null,[a("Click "),s("strong",null,"Create"),a(". Click "),s("strong",null,"Create & create another"),a(" to start a new form. Click "),s("strong",null,"Cancel"),a(" to leave.")])],-1)),o(e,{src:"/images1/project/pj_create_filled.png",alt:"Completed Create Project form for Customer Portal Launch ready to save"}),t[6]||(t[6]=r('<h2 id="view-edit-and-archive" tabindex="-1">View, edit and archive <a class="header-anchor" href="#view-edit-and-archive" aria-label="Permalink to &quot;View, edit and archive&quot;">​</a></h2><p>After you save, the <strong>View</strong> page opens. The top links are <strong>View</strong>, <strong>Edit</strong>, <strong>Tasks</strong> and <strong>Milestones</strong>. <strong>Milestones</strong> shows only when the project allows milestones.</p>',2)),o(e,{src:"/images1/project/pj_view.png",alt:"View page of Customer Portal Launch with General, Additional Information, Statistics and Project Settings sections"}),t[7]||(t[7]=r('<p>The page shows these sections:</p><ul><li><strong>General:</strong> name and description.</li><li><strong>Additional Information:</strong> manager, customer, timeline, allocated and remaining hours, current stage and tags.</li><li><strong>Statistics:</strong> <strong>Total Tasks</strong> and <strong>Milestones Progress</strong>.</li><li><strong>Project Settings:</strong> visibility and what is enabled.</li></ul><p>Below the sections, the <strong>Task Stages</strong> and <strong>Milestones</strong> tabs list the stages and milestones of this project.</p><p>Use the <strong>Chatter</strong> button for messages, followers and activities. See <a href="./../../../getting-started/chatter.html">Chatter</a>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Edit:</strong> opens the same form. Change values and save.</li><li><strong>Delete:</strong> archives the project. It moves to <strong>Archived Projects</strong>.</li><li><strong>Restore:</strong> in <strong>Archived Projects</strong>, brings the project back.</li><li><strong>Force delete:</strong> removes the project for good. It fails if other records still use the project.</li><li><strong>Drag a card:</strong> changes the card order.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Force delete</strong> cannot be undone. Use <strong>Delete</strong> if you may need the project again.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./project-stages-and-milestones.html">Project stages and milestones</a></li><li><a href="./../task-management/create-task.html">Create a task</a></li><li><a href="./project-dashboard.html">Project dashboard</a></li><li><a href="./../get-started/project-settings.html">Project settings</a></li><li><a href="./">Project management</a></li></ul>',9))])}const b=n(c,[["render",h]]);export{_ as __pageData,b as default};
